import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 锁定团队名单版本请求；封榜前提交。
 *
 * <p>名单内成员不得为空、不得重复，且每名成员在同一赛事内只能归属一个团队；
 * 任一名单项不合法时整单拒绝，不生成半份名单，也不改变已有成绩归属。
 *
 * @param members         参赛号列表（赛事内已登记选手；不得重复）
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键）；同键重放首次成员与成绩快照，换名单返回409
 */
public record LockRosterRequest(
        @NotEmpty List<@NotBlank String> members,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.EntryStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 已锁定名单版本中单个成员的固化成绩归属（只读，退赛或后续名单变化都不改写）。
 *
 * @param bib          参赛号
 * @param rank         锁定时固化的全场名次；非 RANKED 为 null
 * @param status       锁定时固化的成绩状态
 * @param finishTimeMs 锁定时固化的原始完赛耗时（毫秒）；计时缺失为 null
 * @param penaltyMs    锁定时固化的生效加时合计毫秒数
 * @param totalTimeMs  锁定时固化的总耗时（毫秒）；非 RANKED 为 null
 * @param memberPoints 成员名次积分；非 RANKED 为 0
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RosterMemberResponse(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int memberPoints
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 一个已锁定名单版本的只读响应：成员成绩归属为锁定时刻快照，永不改写。
 *
 * @param raceId      赛事ID
 * @param teamId      团队ID
 * @param versionNo   名单版本号，团队内从1连续递增
 * @param lockedAt    锁定时间，Unix毫秒时间戳
 * @param teamPoints  锁定时刻固化的团队积分（未剔退赛；后续计分以当前名单/封榜榜为准）
 * @param members     固化成员，按参赛号字典序排列
 */
public record TeamRosterResponse(
        String raceId,
        String teamId,
        int versionNo,
        long lockedAt,
        int teamPoints,
        List<RosterMemberResponse> members
) {
}

