package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 成员退赛请求；不得从已锁定名单中直接删人，只回填退赛生效场次与原因。
 *
 * <p>退赛只影响未封榜的后续计分：已锁定版本固化的成员成绩归属与已封榜团队积分均不重算。
 *
 * @param bib              退赛成员参赛号
 * @param effectiveSession 退赛具体生效场次代码
 * @param reason           退赛原因
 * @param expectedVersion  客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId        全局唯一请求ID（幂等键）
 */
public record WithdrawRosterMemberRequest(
        @NotBlank String bib,
        @NotBlank String effectiveSession,
        @NotBlank @Size(max = 255) String reason,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 当前团队名单中的成员视图：在最新锁定版本固化成绩归属之上叠加当前在队状态。
 *
 * @param bib              参赛号
 * @param state            ACTIVE-在队计分；WITHDRAWN-已退赛，未封榜后续计分剔除
 * @param firstVersionNo   首次入队（被锁定）的名单版本号
 * @param currentVersionNo 当前所属（最新锁定）名单版本号
 * @param effectiveSession 退赛生效场次代码；未退赛为 null
 * @param reason           退赛原因；未退赛为 null
 * @param withdrawnAt      退赛记录时间，Unix毫秒时间戳；未退赛为 null
 * @param memberPoints     在当前版本中固化的名次积分；非 RANKED 为 0
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CurrentRosterMemberResponse(
        String bib,
        String state,
        int firstVersionNo,
        int currentVersionNo,
        String effectiveSession,
        String reason,
        Long withdrawnAt,
        int memberPoints
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 团队当前名单响应：反映最新锁定版本叠加退赛等后续变化；
 * 与“锁定版本（不可变快照）”“已封榜团队成绩（只读）”相区分。
 *
 * @param raceId           赛事ID
 * @param teamId           团队ID
 * @param currentVersionNo 当前最新锁定名单版本号；团队从未锁定名单时为 0
 * @param members          当前成员，按参赛号字典序排列；含已退赛成员（state=WITHDRAWN，不删人）
 */
public record CurrentRosterResponse(
        String raceId,
        String teamId,
        int currentVersionNo,
        List<CurrentRosterMemberResponse> members
) {
}

